package com.ruoyi.paismart.application.intelligence;
import com.ruoyi.paismart.application.billing.QuotaService;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.DriverManagerDataSource;
import org.springframework.jdbc.support.JdbcTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.time.LocalDate;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class ModelCallServiceTest {
    private QuotaService quota;private ModelCallService service;
    @BeforeEach void prepare(){var ds=new DriverManagerDataSource("jdbc:h2:mem:call_"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1","sa","");var db=new JdbcTemplate(ds);db.execute("CREATE TABLE sys_user(user_id BIGINT PRIMARY KEY,status VARCHAR(1),del_flag VARCHAR(1))");db.update("INSERT INTO sys_user VALUES(1,'0','0')");db.execute("CREATE TABLE ps_model_call(id VARCHAR(36) PRIMARY KEY,user_id BIGINT,operation_id VARCHAR(160),scope VARCHAR(20),request_hash VARCHAR(64),status VARCHAR(25),reservation_id VARCHAR(36),response_json CLOB,actual_tokens BIGINT,estimated BOOLEAN,reason VARCHAR(500),created_at TIMESTAMP,updated_at TIMESTAMP,UNIQUE(user_id,scope,operation_id))");quota=mock(QuotaService.class);when(quota.reserve(1L,"model:operation","LLM",10L)).thenReturn(new QuotaService.Reservation("reservation",1L,"LLM","model:operation","BALANCE",10L,null,"RESERVED",LocalDate.now()));service=new ModelCallService(db,new TransactionTemplate(new JdbcTransactionManager(ds)),quota);org.springframework.test.util.ReflectionTestUtils.setField(service,"members",mock(com.ruoyi.paismart.application.MembershipService.class));}
    @Test void completedOperationReplaysResponseAndNeverReservesTwice(){var first=service.begin(1,"operation","LLM",Map.of("prompt","one","model","v1"),10);service.complete(first,Map.of("content","answer"),7,false,false);var replay=service.begin(1,"operation","LLM",Map.of("model","v1","prompt","one"),10);assertEquals("COMPLETED",replay.status());assertTrue(replay.response().contains("answer"));verify(quota,times(1)).reserve(1L,"model:operation","LLM",10L);verify(quota,times(1)).settle("reservation",7L);}
    @Test void changedInputCannotReusePaidOperation(){var call=service.begin(1,"operation","LLM",Map.of("prompt","one"),10);service.complete(call,Map.of(),7,false,false);assertThrows(IllegalStateException.class,()->service.begin(1,"operation","LLM",Map.of("prompt","two"),10));}
    @Test void uncertainRemoteResultDoesNotSendAgainOrInventZeroUsage(){var call=service.begin(1,"operation","LLM",Map.of("prompt","one"),10);service.uncertain(call,"远端结果未知",Map.of());assertThrows(IllegalStateException.class,()->service.begin(1,"operation","LLM",Map.of("prompt","one"),10));verify(quota,never()).release(anyString());service.reconcile(call.id(),3,"根据供应商请求记录核对");verify(quota).settle("reservation",3L);}
    @Test void queryRateIsChargedOnlyForNewBillableEmbeddingCalls(){var rate=mock(com.ruoyi.paismart.application.billing.RateLimitService.class);org.springframework.test.util.ReflectionTestUtils.setField(service,"limits",rate);when(quota.reserve(1L,"model:search:q","EMBEDDING",10L)).thenReturn(new QuotaService.Reservation("queryReservation",1L,"EMBEDDING","model:search:q","BALANCE",10L,null,"RESERVED",LocalDate.now()));var first=service.begin(1,"search:q","EMBEDDING",Map.of("input","one"),10);service.complete(first,Map.of("data",List.of()),4,false,false);service.begin(1,"search:q","EMBEDDING",Map.of("input","one"),10);verify(rate,times(1)).acquireEmbeddingQuery(1L);verify(quota,times(1)).reserve(1L,"model:search:q","EMBEDDING",10L);}
    @Test void documentEmbeddingDoesNotConsumeQueryRequestWindow(){var rate=mock(com.ruoyi.paismart.application.billing.RateLimitService.class);org.springframework.test.util.ReflectionTestUtils.setField(service,"limits",rate);when(quota.reserve(1L,"model:embed:doc:1","EMBEDDING",10L)).thenReturn(new QuotaService.Reservation("uploadReservation",1L,"EMBEDDING","model:embed:doc:1","BALANCE",10L,null,"RESERVED",LocalDate.now()));service.begin(1,"embed:doc:1","EMBEDDING",Map.of("input","one"),10);verify(rate,never()).acquireEmbeddingQuery(anyLong());}
    @Test void revokedBusinessEligibilityCannotFreezeQuotaForQueuedWork(){var members=mock(com.ruoyi.paismart.application.MembershipService.class);doThrow(new org.springframework.security.access.AccessDeniedException("业务资格已撤销")).when(members).requireEligible(1);org.springframework.test.util.ReflectionTestUtils.setField(service,"members",members);assertThrows(org.springframework.security.access.AccessDeniedException.class,()->service.begin(1,"operation","LLM",Map.of("prompt","one"),10));verifyNoInteractions(quota);}
}

